// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_walletAcceptsArbitraryCalldata(uint256 value, bytes calldata extra) public {
        value = bound(value, 0, 100 ether);
        bytes memory data = abi.encodePacked(hex"deadbeef", extra);
        vm.deal(address(this), value);

        uint256 beforeCount = c.depositsCount();
        (bool ok, ) = address(c).call{value: value}(data);

        assertTrue(ok, "wallet must accept call carrying arbitrary calldata (fallback)");
        assertEq(c.depositsCount(), beforeCount + 1, "deposit must be recorded");
        assertEq(address(c).balance, value, "forwarded Ether must be accepted");
    }
}
